#!/usr/bin/env python3
"""Generate the pinned dungeon enemy pools and scoped native loot repairs."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "metadata/dimensional_dungeons.json"
DATA = ROOT / "overrides/kubejs/data"


def source():
    return json.loads(SOURCE.read_text(encoding="utf-8"))


def config(data):
    lines = [
        "# Generated by scripts/dimensional_dungeons.py; edit metadata/dimensional_dungeons.json.",
        "# Native room layouts, finite structure spawns and Nether Fortress enemy pools are retained.",
        "# The encounter bridge supplies additional difficulty. Do not multiply native base HP again.",
        "# DD still applies its authored 1.5x HP, Strength II and fire resistance to Enemy2/keyholders.",
        "[enemySets]",
    ]
    for name, enemies in data["enemy_sets"].items():
        lines.append(f"{name} = {json.dumps(enemies)}")
    lines.extend(["basicEnemyHealthScaling = 1.0", "advancedEnemyHealthScaling = 1.0", "numberOfThemes = 3"])
    for number, theme in data["themes"].items():
        lines.extend(["", f"# {theme['name']}: ordinary hostiles, no dimension bosses or progression trophies.",
                      f"[dungeonTheme{number}]",
                      f"themeEnemySet1_{number} = {json.dumps(theme['enemy_set_1'])}",
                      f"themeEnemySet2_{number} = {json.dumps(theme['enemy_set_2'])}",
                      f"themeEnemyHealthScaling{number} = 1.0"])
    return "\n".join(lines) + "\n"


def item_entry(row):
    item, weight, minimum, maximum = row
    count = minimum if minimum == maximum else {"type": "minecraft:uniform", "min": minimum, "max": maximum}
    return {"type": "minecraft:item", "name": item, "weight": weight,
            "functions": [{"function": "minecraft:set_count", "count": count, "add": False}]}


def table_path(table):
    namespace, name = table.split(":", 1)
    if namespace != "dimdungeons" or not name.startswith(("chest/", "chests/")) or ".." in name:
        raise ValueError(f"Unscoped Dimensional Dungeons table: {table}")
    return DATA / namespace / "loot_table" / f"{name}.json"


def json_text(value):
    return json.dumps(value, ensure_ascii=False, indent=2) + "\n"


def outputs():
    data = source()
    result = {ROOT / "overrides/config" / data["common_config"]: config(data)}
    for old, alias in data["legacy_loot_aliases"].items():
        result[table_path(old)] = json_text({"type": "minecraft:chest", "pools": [{
            "rolls": 1, "bonus_rolls": 0,
            "entries": [{"type": "minecraft:loot_table", "value": alias["target"]}],
        }]})
    for name, kit in data["kit_overrides"].items():
        entries = [item_entry(row) for row in kit["items"]]
        entries.extend({"type": "minecraft:loot_table", "value": table, "weight": weight}
                       for table, weight in kit.get("tables", []))
        result[table_path(name)] = json_text({"type": "minecraft:chest", "pools": [{
            "name": "qm_dimensional_dungeons_" + name.rsplit("/", 1)[-1],
            "rolls": kit["rolls"], "bonus_rolls": 0, "entries": entries,
        }]})
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    stale = []
    for path, content in outputs().items():
        if args.check:
            if not path.is_file() or path.read_text(encoding="utf-8") != content:
                stale.append(path.relative_to(ROOT).as_posix())
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
    if stale:
        raise SystemExit("Stale Dimensional Dungeons policy: " + ", ".join(stale))
    print("Dimensional Dungeons pools and loot repairs are synchronized.")


if __name__ == "__main__":
    main()
